    "deep_dive": "Il codice civile non contiene una definizione espressa di matrimonio; essa si ricava indirettamente dall'art. 1 della legge sul divorzio (L. 898/1970), che consente lo scioglimento quando la «comunione spirituale e materiale tra i coniugi» non può essere mantenuta o ricostituita.",
    "source_label": "Lezione 008 · Il matrimonio (Prof.ssa Galluzzo)",
    "source_excerpt": "arsi e il diritto di costituire una famiglia devono essere garantiti dalle leggi nazionali. Non si trova nella disciplina codicistica alcuna definizione relativa al matrimonio, ricavabile peraltro indirettamente da quelle norme che regolano lo scioglimento del vincolo coniugale. Il divorzio infatti, come vedremo, è possibile quando “la comunione di vita materiale e spirituale tra coniugi” non può più essere mantenuta o ricostituita (art 1). Il matrimonio viene pertanto identificato nel legame tra due persone, tendenzialmente per la vita, a fondamento del quale si pone una condivisione di aspetti sia patrimoniali che morali. È bene sottolineare come la comune concezione sociale che considera l’unione matrimoniale un",
