    "deep_dive": "L'ordinamento italiano riconosce agli effetti civili tre forme di celebrazione: il matrimonio civile (artt. 84 ss. c.c.), il matrimonio concordatario cattolico (art. 82 c.c.) e il matrimonio celebrato davanti a ministri di culti ammessi nello Stato (art. 83 c.c.).",
    "source_label": "Lezione 008 · Il matrimonio (Prof.ssa Galluzzo)",
    "source_excerpt": "ore, la durata del rapporto sia in grado di sanare tali vizi. Al contrario pur in presenza di un matrimonio-atto valido un rapporto viziato, ad esempio dalla mancanza di comunione morale e materiale, è sufficiente a sciogliere il vincolo. LE FORME DI CELEBRAZIONE DEL MATRIMONIO. L’ordinamento giuridico italiano attribuisce ai cittadini la possibilità di scegliere tra diverse forme matrimoniali: - il matrimonio civile, interamente regolato dalle leggi italiane - il matrimonio concordatario che viene celebrato secondo il diritto canonico e che acquista effetti civili solamente in seguito a una trascrizione dell’atto di celebrazione nei registri dello stato civile. In vir",
