    "source_label": "Lezione 012 · Il matrimonio concordatario (Prof.ssa Galluzzo)",
    "source_excerpt": "ale ai fini dell’efficacia del matrimonio è la trascrizione. La trascrizione dell’atto di matrimonio nei registri dello stato civile consente dunque al vincolo religioso di avere effetti civili, che si producono non dal giorno della trascrizione stessa ma dal giorno delle nozze. È costitutiva della stessa efficacia civile del vincolo: se manca, il matrimonio resta unicamente religioso. L’art 8 dell’Accordo del 1984 consente di individuare due tipi di trascrizione, quella tempestiva che ha luogo quando il parroco trasmette l’atto di matrimonio entro 5 giorni dalle nozze e quella tardiva. I coniugi infatti possono anche decidere di non far trascrivere subito il ",
