    "source_excerpt": "za che inficia il vincolo religioso nel caso di matrimonio concordatario, per essere efficace nell’ordinamento italiano e produrre quindi anche la cessazione degli effetti civili deve essere sottoposta a un procedimento di delibazione da parte della Corte d’Appello. LA NORMATIVA La materia è regolata: - dagli artt. 150 e seguenti cod civ relativi alla separazione, - dalla Legge 1 dicembre 1970, n 898 modificata dalla Legge 6 marzo 1987, n 74 relativa allo scioglimento del matrimonio, - dagli artt 473 bis cod proc civ (introdotti dal D Lgs 149 del 2022) per quanto riguarda gli aspetti processuali. Si evidenzia anche il Regolamento Europeo ",
