    "exam_answer": "la separazione",
    "deep_dive": "La separazione personale dei coniugi non estingue né scioglie il vincolo matrimoniale, ma lo attenua sospendendo alcuni doveri coniugali. Al contrario, la morte (e la morte presunta), il divorzio e la cessazione degli effetti civili del matrimonio concordatario comportano lo scioglimento del vincolo.",
    "source_label": "Lezione 018 · La crisi coniugale (Prof.ssa Galluzzo)",
    "source_excerpt": "ie attribuiti alla competenza del tribunale ordinario, del giudice tutelare e del tribunale per i minorenni. In sostanza in relazione a tutte le questioni attinenti alla famiglia (tranne le adozioni) si applicano le stesse regole processuali. LA SEPARAZIONE PERSONALE DEI CONIUGI La separazione tra coniugi non estingue il vincolo matrimoniale ma lo attenua: incide infatti unicamente sugli effetti e non fa cadere l’atto del matrimonio né ex tunc, come nella sentenza di invalidità, né ex nunc come nel divorzio. I coniugi separati non possono contrarre nuovo matrimonio e alcuni degli obblighi matrimoniali sono sospesi, mentre altri vengono solamente attenuati. Permangono inoltre tutte quelle conseguenze che la ",
