    "source_label": "Lezione 027 · Rapporti familiari e responsabilità civile (Prof.ssa Galluzzo)",
    "source_excerpt": "er le convivenze di fatto. Il rapporto genitori figli La giurisprudenza ha più volte riconosciuto ipotesi di danni in relazione ai doveri gravanti sui genitori nei riguardi dei figli o in relazione alle responsabilità che un genitore ha nei riguardi dell’altro rispetto ai figli. La tematica si inserisce in un filone giurisprudenziale e dottrinale che, da tempo, ha riconosciuto il danno da privazione della figura genitoriale. Tale danno si realizza nell’ipotesi di mancanza di uno dei due genitori e pertanto di lesione del diritto alla bigenitorialità, ossia nella privazione del diritto di ogni figlio ad avere un padre ed una madre e a poter contare sul loro aiuto non solo economico ma anche e sopratt",
