    "deep_dive": "Una volta accertata la genitorialità biologica, è risarcibile il danno (patrimoniale e non patrimoniale) da mancato riconoscimento del figlio nato fuori dal matrimonio, poiché l'obbligo di mantenere ed educare ex artt. 147 e 148 c.c. è connesso esclusivamente alla procreazione (Cass. 15148/2022).",
