    "source_excerpt": "LO SCIOGLIMENTO DELL’UNIONE CIVILE\nLa legge 20 maggio 2016 n 76 prevede e regolamenta, le unioni civili, ossia\nforme di relazioni affettive formate da persone dello stesso sesso.\nCon tale normativa sono definiti e disciplinati la costituzione dell’unione, gli\nimpedimenti, la registrazione, nonché i diritti e doveri che si instaurano tra i\ncomponenti (si veda lezione precedente).\nL’unione civile, come ogni altra forma di relazione, può andare incontro a crisi.\nLa legge 76 del 2016 all’art 1 commi 21 ss. regolamenta espressamente lo\nscioglimento prevedendo che l’unione viene meno:\n• per morte o ",
