    "deep_dive": "L'art. 29 della Costituzione riconosce i diritti della famiglia come società naturale fondata sul matrimonio (unione stabile tra uomo e donna), mentre le unioni civili e le coppie omosessuali trovano tutela costituzionale nell'art. 2 Cost.",
