    "source_excerpt": "ibuiti diritti e doveri (si veda lezioni precedenti). Fino a tale momento peraltro la questione è stata gestita dalla giurisprudenza che di fronte alle varie richieste delle coppie ha per lo più sempre richiamato al rispetto della legge. In tal senso si evidenzia la posizione della Corte Costituzionale che in varie riprese ha ribadito che le unioni omosessuali non possono essere ritenute omogenee al matrimonio, che secondo il dettato costituzionale e la vigente normativa del codice civile è l' unione stabile tra un uomo e una donna (Corte Costituzionale 4 del 2011, 138 del 2010, 276 del 2010). La situazione nei Paesi stranieri è quanto mai variegata. Si consideri ad esempio che in vari Stati, anche europei è ammessa la registrazione formale di unioni di fatto, in alcuni casi riservata ai soli omosessuali, ",
