    "deep_dive": "Prima della riforma del diritto di famiglia del 1975, l'espressione «figlio illegittimo» indicava il figlio nato da genitori non uniti in matrimonio, con un forte disvalore giuridico e sociale; dal 1975 è stata sostituita da «figlio naturale» e dal 2012 è stata eliminata ogni distinzione.",
