    "source_excerpt": "o del figlio. La Costituzione. Il primo passo in tal senso effettuato dal nostro ordinamento risale all’approvazione della Carta Costituzionale che all’art 30 stabilisce che è dovere e diritto dei genitori mantenere educare e istruire i figli, anche se nati fuori dal matrimonio. All’epoca la contrapposizione tra i due tipi di filiazione, legittima e illegittima, era netta. Lo stesso termine illegittimo indicava un forte disvalore sociale e giuridico verso la filiazione al di fuori del matrimonio. Solo il figlio nato nel matrimonio aveva una piena tutela, mentre per gli altri figli vi era un trattamento deteriore e ciò allo scopo di proteggere e rafforzare la famiglia legittima. Si consideri che il matrimonio era indissolubile e che il figlio adulterino, nato da genitori ",
