    "deep_dive": "L'art. 74 c.c., come modificato dalla Legge n. 219/2012, ha unificato la nozione di parentela eliminando ogni distinzione basata sul matrimonio. Il vincolo di parentela tra persone che discendono dallo stesso stipite sorge quindi sia nella filiazione dentro il matrimonio sia in quella fuori del matrimonio (oltre che nell'adozione piena dei minori).",
    "source_label": "Lezione 034 · Il diritto del figlio ad avere una famiglia (Prof.ssa Galluzzo)",
    "source_excerpt": "IL DIRITTO DEL FIGLIO AD AVERE UNA FAMIGLIA LA PARENTELA (ART 74 COD CIV) L’art 74 cod civ, che stabilisce le regole alla base del rapporto di parentela è stato profondamente modificato con la Legge 219 del 2012. Secondo la nuova norma il vincolo di parentela che lega le persone che discendono dallo stesso stipite si instaura sia nel caso in cui la filiazione sia avvenuta all’interno del matrimonio, che nel caso in cui la filiazione sia avvenuta al di fuori di un rapporto coniugale. La parentela cui si riferisce la disposizione in esame riguarda sia i rapporti in linea retta, che, quelli in linea collaterale, come risulta dall’art 75 cod civ. La novità è molto rilevante. Viene estesa la parentela senza distinguere tra filiazione dentro o fuori del matrimoni",
