    "source_label": "Lezione 043 · L’adozione piena (Prof.ssa Galluzzo)",
    "source_excerpt": "L’ADOZIONE PIENA\nL’adozione piena, regolata dagli artt 6 e seguenti della legge 184 del 1983,\nha lo scopo di trovare una famiglia a un minore quando questi si trova in una\nsituazione di abbandono. Tutta la disciplina è fondata sul rispetto del preminente\ninteresse del minore.\nSi parla di adozione nazionale quando l’adozione riguarda minori italiani o\ncomunque presenti sul territorio italiano.\nÈ invece internazionale l’adozione di un minore straniero da parte di una coppia\nitaliana nonché, caso ben più raro, l’adozione di un minore italiano da parte di\nconiugi stranieri.\nEFFETTI\nL’adozione crea",
